[metadata] {"type": "create", "filePath": "/app/output/digital-divide-chart.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>The Digital Divide — Internet Penetration Inequality 2023</title>
  <link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=IBM+Plex+Sans:wght@300;400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
  <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
  <style>
    :root {
      --bg: #f7f4ef;
      --surface: #ffffff;
      --surface-tint: #f0ece4;
      --border: rgba(0,0,0,0.10);
      --border-strong: rgba(0,0,0,0.22);
      --text: #1a1714;
      --text-dim: #5a5550;
      --text-faint: #9a958f;
      --accent-rust: #b84c20;
      --accent-rust-dim: #f3e8e2;
      --accent-slate: #1e3a5f;
      --accent-slate-dim: #e0e8f0;
      --accent-gold: #c0872a;
      --accent-gold-dim: #fdf0d8;
      --accent-sage: #4a7c59;
      --accent-sage-dim: #e4f0e8;
      --ssa-color: #b84c20;
      --sa-color: #c0872a;
      --eu-color: #1e3a5f;
      --na-color: #4a7c59;
      --font-serif: 'Instrument Serif', Georgia, serif;
      --font-sans: 'IBM Plex Sans', system-ui, sans-serif;
      --font-mono: 'IBM Plex Mono', 'Courier New', monospace;
    }
    @media (prefers-color-scheme: dark) {
      :root {
        --bg: #131210;
        --surface: #1d1b18;
        --surface-tint: #252320;
        --border: rgba(255,255,255,0.09);
        --border-strong: rgba(255,255,255,0.20);
        --text: #e8e3db;
        --text-dim: #a09890;
        --text-faint: #625e58;
        --accent-rust: #d4693e;
        --accent-rust-dim: #2a1e18;
        --accent-slate: #7ba8d4;
        --accent-slate-dim: #182030;
        --accent-gold: #d4a050;
        --accent-gold-dim: #2a2010;
        --accent-sage: #6fa882;
        --accent-sage-dim: #182820;
        --ssa-color: #d4693e;
        --sa-color: #d4a050;
        --eu-color: #7ba8d4;
        --na-color: #6fa882;
      }
    }
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { font-size: 16px; }
    body {
      background: var(--bg);
      background-image: radial-gradient(ellipse 80% 40% at 50% -10%, rgba(176,140,100,0.08) 0%, transparent 70%);
      color: var(--text);
      font-family: var(--font-sans);
      min-height: 100vh;
      padding: 0 0 80px;
    }

    /* ── Header ── */
    .masthead {
      border-bottom: 2px solid var(--border-strong);
      padding: 48px 60px 36px;
      max-width: 1320px;
      margin: 0 auto;
    }
    .masthead-kicker {
      font-family: var(--font-mono);
      font-size: 11px;
      letter-spacing: 0.16em;
      text-transform: uppercase;
      color: var(--accent-rust);
      margin-bottom: 18px;
    }
    .masthead-title {
      font-family: var(--font-serif);
      font-size: clamp(2.4rem, 5vw, 3.8rem);
      font-weight: 400;
      line-height: 1.08;
      color: var(--text);
      max-width: 760px;
    }
    .masthead-title em {
      font-style: italic;
      color: var(--accent-rust);
    }
    .masthead-meta {
      display: flex;
      align-items: center;
      gap: 32px;
      margin-top: 24px;
      flex-wrap: wrap;
    }
    .masthead-meta-item {
      display: flex;
      flex-direction: column;
      gap: 3px;
    }
    .masthead-meta-label {
      font-family: var(--font-mono);
      font-size: 10px;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--text-faint);
    }
    .masthead-meta-value {
      font-size: 13px;
      font-weight: 500;
      color: var(--text-dim);
    }
    .masthead-divider { width: 1px; height: 36px; background: var(--border-strong); }

    /* ── Region Legend ── */
    .region-legend {
      display: flex;
      gap: 28px;
      flex-wrap: wrap;
      padding: 16px 60px;
      border-bottom: 1px solid var(--border);
      max-width: 1320px;
      margin: 0 auto;
      background: var(--surface-tint);
    }
    .legend-item {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      font-weight: 500;
      color: var(--text-dim);
    }
    .legend-swatch {
      width: 22px; height: 4px;
      border-radius: 2px;
      flex-shrink: 0;
    }
    .legend-swatch.ssa { background: var(--ssa-color); }
    .legend-swatch.sa  { background: var(--sa-color); }
    .legend-swatch.eu  { background: var(--eu-color); }
    .legend-swatch.na  { background: var(--na-color); }

    /* ── Layout ── */
    .content-wrap {
      max-width: 1320px;
      margin: 0 auto;
      padding: 0 60px;
    }

    /* ── Section label ── */
    .section-label {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 40px 0 20px;
    }
    .section-label-dot {
      width: 8px; height: 8px;
      border-radius: 50%;
      flex-shrink: 0;
    }
    .section-label-text {
      font-family: var(--font-mono);
      font-size: 11px;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--text-faint);
    }
    .section-heading {
